/* Warm original artwork quietly. Critical images load normally; background work never blocks navigation. */
import {imageVariant} from './image-variants.js';
import {siteURL} from './site-paths.js';
const HER_ART=["/assets/games-revision/her/game/slot-frame.png", "/assets/games-revision/her/game/slot-empty.png", "/assets/games-revision/her/game/solid-scene-generic.png", "/assets/games-revision/her/game/solid-scene-shangguan-waner.png", "/assets/games-revision/her/game/solid-scene-princess-taiping.png", "/assets/games-revision/her/game/choice-area-frame.png", "/assets/games-revision/her/game/choice-normalized/empress-wei.png", "/assets/games-revision/her/game/choice-normalized/lake-trip.png", "/assets/games-revision/her/game/choice-normalized/poetry-scene.png", "/assets/games-revision/her/game/choice-normalized/power.png", "/assets/games-revision/her/game/choice-normalized/shangguan-waner.png", "/assets/games-revision/her/game/choice-normalized/emperor-zhongzong.png", "/assets/games-revision/her/game/choice-normalized/edict.png", "/assets/games-revision/her/game/choice-normalized/balance.png", "/assets/games-revision/her/game/choice-normalized/li-dan.png", "/assets/games-revision/her/game/choice-normalized/princess-taiping.png", "/assets/games-revision/her/game/choice-normalized/li-chongmao.png", "/assets/games-revision/her/game/choice-normalized/death.png", "/assets/games-revision/her/game/choice-normalized/banquet.png", "/assets/games-revision/her/game/level-three/lake-trip-shangguan-waner-taiping.png", "/assets/games-revision/her/game/level-three/lake-trip-choice.png", "/assets/games-revision/her/game/level-three/shangguan-waner-choice.png", "/assets/games-revision/her/game/level-three/princess-taiping-choice.png", "/assets/games-revision/her/game/level-three/poetry-choice.png", "/assets/games-revision/her/game/level-three/princess-taiping-close-side-half.png", "/assets/games-revision/her/game/level-three/shangguan-waner-close-side-half.png", "/assets/games-revision/her/game/level-three/scene-poetry.png", "/assets/games-revision/her/game/level-three/banquet-choice.png", "/assets/games-revision/her/game/level-three/poetry-shangguan-waner-princess-taiping-banquet.png", "/assets/games-revision/her/game/level-three/scene-lake-trip.png", "/assets/games-revision/her/game/level-three/scene-banquet.png", "/assets/games-revision/her/game/level-three/banquet-shangguan-waner-princess-taiping.png", "/assets/games-revision/her/game/final-chapter/resolved-1.png", "/assets/games-revision/her/game/final-chapter/resolved-2.png", "/assets/games-revision/her/game/final-chapter/resolved-3.png", "/assets/games-revision/her/game/final-chapter/initial-1.png", "/assets/games-revision/her/game/final-chapter/initial-2.png", "/assets/games-revision/her/game/final-chapter/initial-3.png", "/assets/games-revision/her/ui/hint-magnifier.png"];
let data=null,active=0,started=false,scheduled=false;const queued=new Set(),done=new Set(),queue=[];
const picture=/\.(?:png|jpe?g|webp|svg)(?:[?#].*)?$/i;
const local=s=>typeof s==='string'&&s.startsWith('/')&&/\/(?:assets|website-assets)\//.test(s)&&picture.test(s);
const images=value=>{const found=[];function visit(v){if(local(v))found.push(v);else if(Array.isArray(v))v.forEach(visit);else if(v&&typeof v==='object')Object.values(v).forEach(visit)}visit(value);return [...new Set(found)]};
function enqueue(url,front=false){const href=siteURL(imageVariant(url));if(done.has(href)||queued.has(href))return;queued.add(href);front?queue.unshift(href):queue.push(href)}
function pump(){scheduled=false;if(document.hidden)return;while(active<2&&queue.length){const href=queue.shift();active++;const img=new Image();img.decoding='async';img.fetchPriority='low';const finish=()=>{active--;done.add(href);queued.delete(href);img.onload=img.onerror=null;schedule()};img.onload=finish;img.onerror=finish;img.src=href}}
function schedule(){if(scheduled)return;scheduled=true;if('requestIdleCallback'in window)requestIdleCallback(pump,{timeout:1600});else setTimeout(pump,180)}
export function warmProject(id){if(!data)return;const p=data.projects.find(x=>x.id===id);if(!p)return;images(p).reverse().forEach(src=>enqueue(src,true));schedule()}
export function startAssetLoading(content){if(content)data=content;if(started)return;started=true;const launch=async()=>{if(!data){try{data=await(await fetch(siteURL('/content.json'))).json()}catch{return}}images(data.projects.map(p=>p.hero)).forEach(s=>enqueue(s));for(let i=1;i<=18;i++)enqueue(`/assets/games-revision/her/wind/${String(i).padStart(2,'0')}.webp`);for(const n of ['shangguan-waner','princess-taiping','power','banquet'])enqueue(`/assets/games-revision/her/game/choice-normalized/${n}.png`);HER_ART.forEach(s=>enqueue(s));images(data).forEach(s=>enqueue(s));schedule()};if(document.readyState==='complete')setTimeout(launch,500);else window.addEventListener('load',()=>setTimeout(launch,500),{once:true});document.addEventListener('visibilitychange',()=>{if(!document.hidden)schedule()})}
